import { type VariantProps, cva } from 'class-variance-authority';

export { default as CodeBlock } from './CodeBlock.vue';
export { default as CodeBlockActions } from './CodeBlockActions.vue';
export { default as CodeBlockContent } from './CodeBlockContent.vue';
export { default as CodeBlockCopyButton } from './CodeBlockCopyButton.vue';
export { default as CodeBlockExpandButton } from './CodeBlockExpandButton.vue';
export { default as CodeBlockFooter } from './CodeBlockFooter.vue';
export { default as CodeBlockHeader } from './CodeBlockHeader.vue';
export { default as CodeBlockLine } from './CodeBlockLine.vue';
export { default as CodeBlockTabs } from './CodeBlockTabs.vue';
export { default as CodeBlockTabsContent } from './CodeBlockTabsContent.vue';
export { default as CodeBlockTabsList } from './CodeBlockTabsList.vue';
export { default as CodeBlockTabsTrigger } from './CodeBlockTabsTrigger.vue';
export { default as CodeBlockTitle } from './CodeBlockTitle.vue';
export { default as CodeBlockWrapButton } from './CodeBlockWrapButton.vue';
export {
  type CodeBlockHighlightOptions,
  type CodeBlockThemes,
  codeBlockLanguageAliases,
  codeBlockLanguages,
  highlightCode,
  loadCodeBlockHighlighter,
  resolveCodeBlockLanguage,
} from '@/components/ui/code-block/highlighter';
export {
  type CodeBlockLineVariant,
  type CodeToken,
  type LineSelector,
  type PrepareCodeOptions,
  type WordMatcher,
  prepareCode,
} from '@/components/ui/code-block/lines';
export {
  type UseHighlightedCodeOptions,
  type UseHighlightedCodeReturn,
  useHighlightedCode,
} from '@/components/ui/code-block/use-highlighted-code';

export const codeBlockVariants = cva('sigma-ui-code-block', {
  variants: {
    variant: {
      default: 'sigma-ui-code-block--default',
      destructive: 'sigma-ui-code-block--destructive',
    },
    size: {
      default: 'sigma-ui-code-block--size-default',
      sm: 'sigma-ui-code-block--size-sm',
    },
  },
  defaultVariants: {
    variant: 'default',
    size: 'default',
  },
});

export type CodeBlockVariants = VariantProps<typeof codeBlockVariants>;

import type { Ref } from 'vue';
import { createContext } from 'reka-ui';

export type CodeBlockVariant = 'default' | 'destructive';
export type CodeBlockSize = 'default' | 'sm';

export interface CodeBlockContext {
  /** Whether long lines wrap. */
  wrap: Ref<boolean>;
  /** Whether a collapsed block shows all of its lines. */
  expanded: Ref<boolean>;
  /** The text the copy button copies, set by the mounted `CodeBlockContent`. */
  copyValue: Ref<string | undefined>;
  /** Whether the mounted content is taller than its `collapsedHeight`. */
  collapsible: Ref<boolean>;
  /** Id of the mounted content, for `aria-controls`. */
  contentId: Ref<string | undefined>;
  /** Id of the title, for `aria-labelledby`. */
  titleId: Ref<string | undefined>;
  setWrap: (value: boolean) => void;
  setExpanded: (value: boolean) => void;
}

export const [injectCodeBlockContext, provideCodeBlockContext] = createContext<CodeBlockContext>('CodeBlock');

/** Reads the CodeBlock context, or `null` outside a `CodeBlock`. */
export function useCodeBlockContext(): CodeBlockContext | null {
  return injectCodeBlockContext(null);
}

/** Formats a number or a CSS length for a style property. */
export function toCssLength(value: string | number | undefined): string | undefined {
  if (value === undefined || value === '') {
    return undefined;
  }

  return typeof value === 'number' ? `${value}px` : value;
}

export type CodeBlockLineVariant = 'default' | 'added' | 'removed' | 'highlighted';

/** A set of 1-based line numbers: `"1,4-6"` or `[1, 4, 5, 6]`. */
export type LineSelector = string | number[];

/** A word, phrase, or pattern to mark inside the code. */
export type WordMatcher = string | RegExp;

export interface PrepareCodeOptions {
  /** Treat a leading `+`, `-`, or space on each line as a diff marker. */
  diff?: boolean;
  /** Read and strip `[!code highlight|focus|++|--|word:…]` comments. */
  notation?: boolean;
}

export interface PreparedLine {
  /** Line text without diff markers or notation comments. */
  text: string;
  /** 1-based line number in the code that was passed in. */
  sourceLine: number;
  /** State set by a diff marker or a notation comment. */
  variant: CodeBlockLineVariant;
  /** Whether a `[!code focus]` comment marked the line. */
  focused: boolean;
  /** Words that a `[!code word:…]` comment marked on this line. */
  words: string[];
}

export interface PreparedCode {
  /** The code to display and highlight, one entry per rendered line. */
  lines: PreparedLine[];
  /** The rendered text, joined with newlines. Pass this to the highlighter. */
  code: string;
  /** The text to copy: rendered text without removed lines. */
  copyText: string;
}

/** Normalizes line endings and drops one trailing newline. */
export function normalizeCode(code: string): string {
  const normalized = code.replace(/\r\n?/g, '\n');
  return normalized.endsWith('\n') ? normalized.slice(0, -1) : normalized;
}

export function splitLines(code: string): string[] {
  return normalizeCode(code).split('\n');
}

/** Parses `"1,4-6"` or a number array into a set of positive line numbers. */
export function parseLineSelector(selector: LineSelector | undefined | null): Set<number> {
  const lines = new Set<number>();

  if (!selector) {
    return lines;
  }

  if (Array.isArray(selector)) {
    selector.filter(line => Number.isInteger(line) && line > 0).forEach(line => lines.add(line));
    return lines;
  }

  for (const part of selector.split(',')) {
    const match = part.trim().match(/^(\d+)(?:\s*-\s*(\d+))?$/);

    if (!match) {
      continue;
    }

    const first = Number(match[1]);
    const last = match[2] === undefined ? first : Number(match[2]);
    const [start, end] = first <= last ? [first, last] : [last, first];

    for (let line = Math.max(start, 1); line <= end; line++) {
      lines.add(line);
    }
  }

  return lines;
}

const NOTATION_PATTERN = /\s*(?:\/\/|#|--|<!--|\/\*|\{\/\*|;)\s*\[!code ([^\]]+)\]\s*(?:-->|\*\/\}?)?\s*$/;

interface Notation {
  kind: 'highlight' | 'focus' | 'added' | 'removed' | 'word';
  count: number;
  word?: string;
}

function parseNotation(value: string): Notation | null {
  const [name, ...rest] = value.trim().split(':');
  const argument = rest.join(':');
  const count = /^\d+$/.test(argument) ? Number(argument) : 1;

  switch (name) {
    case 'highlight':
    case 'hl':
      return { kind: 'highlight', count };
    case 'focus':
      return { kind: 'focus', count };
    case '++':
      return { kind: 'added', count };
    case '--':
      return { kind: 'removed', count };

    case 'word': {
      const separator = argument.lastIndexOf(':');
      const hasCount = separator > 0 && /^\d+$/.test(argument.slice(separator + 1));

      return {
        kind: 'word',
        word: hasCount ? argument.slice(0, separator) : argument,
        count: hasCount ? Number(argument.slice(separator + 1)) : Number.POSITIVE_INFINITY,
      };
    }

    default:
      return null;
  }
}

function readDiffMarker(text: string): { text: string; variant: CodeBlockLineVariant } {
  if (/^(\+\+\+|---)( |$)/.test(text)) {
    return { text, variant: 'default' };
  }

  if (text.startsWith('+')) {
    return { text: text.slice(1), variant: 'added' };
  }

  if (text.startsWith('-')) {
    return { text: text.slice(1), variant: 'removed' };
  }

  return { text: text.startsWith(' ') ? text.slice(1) : text, variant: 'default' };
}

/**
 * Splits code into rendered lines, reading diff markers and notation comments.
 * The component and `useHighlightedCode` both call it, so their lines match.
 */
export function prepareCode(code: string, options: PrepareCodeOptions = {}): PreparedCode {
  const lines: PreparedLine[] = [];
  const pendingWords: { word: string; remaining: number }[] = [];
  const pending: { kind: Exclude<Notation['kind'], 'word'>; remaining: number }[] = [];

  splitLines(code).forEach((raw, index) => {
    let text = raw;
    let variant: CodeBlockLineVariant = 'default';
    let focused = false;
    const notations: Notation[] = [];

    if (options.diff) {
      ({ text, variant } = readDiffMarker(text));
    }

    if (options.notation) {
      let match = text.match(NOTATION_PATTERN);

      while (match) {
        const notation = parseNotation(match[1]);

        if (!notation) {
          break;
        }

        notations.unshift(notation);
        text = text.slice(0, match.index);
        match = text.match(NOTATION_PATTERN);
      }

      // A comment on its own line only marks words for the lines after it.
      if (notations.length > 0 && text.trim() === '' && notations.every(notation => notation.kind === 'word')) {
        notations.forEach(notation => pendingWords.push({ word: notation.word ?? '', remaining: notation.count }));
        return;
      }
    }

    const words: string[] = [];

    for (const entry of pendingWords) {
      if (entry.remaining > 0 && entry.word) {
        words.push(entry.word);
        entry.remaining--;
      }
    }

    for (const notation of notations) {
      if (notation.kind === 'word') {
        if (notation.word) {
          words.push(notation.word);
          pendingWords.push({ word: notation.word, remaining: notation.count - 1 });
        }

        continue;
      }

      pending.push({ kind: notation.kind, remaining: notation.count });
    }

    for (const entry of pending) {
      if (entry.remaining <= 0) {
        continue;
      }

      entry.remaining--;

      if (entry.kind === 'focus') {
        focused = true;
      } else if (entry.kind === 'highlight') {
        variant = variant === 'default' ? 'highlighted' : variant;
      } else {
        variant = entry.kind;
      }
    }

    lines.push({ text, sourceLine: index + 1, variant, focused, words });
  });

  return {
    lines,
    code: lines.map(line => line.text).join('\n'),
    copyText: lines.filter(line => line.variant !== 'removed').map(line => line.text).join('\n'),
  };
}

export interface ResolveVariantOptions {
  highlightLines?: Set<number>;
  addedLines?: Set<number>;
  removedLines?: Set<number>;
}

/** Applies line selectors on top of the variant read from the code. Removed wins over added, added over highlighted. */
export function resolveLineVariant(line: PreparedLine, options: ResolveVariantOptions): CodeBlockLineVariant {
  if (line.variant === 'removed' || options.removedLines?.has(line.sourceLine)) {
    return 'removed';
  }

  if (line.variant === 'added' || options.addedLines?.has(line.sourceLine)) {
    return 'added';
  }

  if (line.variant === 'highlighted' || options.highlightLines?.has(line.sourceLine)) {
    return 'highlighted';
  }

  return 'default';
}

/** Returns sorted, merged `[start, end)` ranges of every match in the text. */
export function findWordRanges(text: string, matchers: readonly WordMatcher[]): [number, number][] {
  const ranges: [number, number][] = [];

  for (const matcher of matchers) {
    if (typeof matcher === 'string') {
      if (!matcher) {
        continue;
      }

      let index = text.indexOf(matcher);

      while (index !== -1) {
        ranges.push([index, index + matcher.length]);
        index = text.indexOf(matcher, index + matcher.length);
      }

      continue;
    }

    const pattern = new RegExp(matcher.source, matcher.flags.includes('g') ? matcher.flags : `${matcher.flags}g`);

    for (const match of text.matchAll(pattern)) {
      if (match[0].length > 0 && match.index !== undefined) {
        ranges.push([match.index, match.index + match[0].length]);
      }
    }
  }

  ranges.sort((first, second) => first[0] - second[0] || second[1] - first[1]);

  const merged: [number, number][] = [];

  for (const range of ranges) {
    const last = merged.at(-1);

    if (last && range[0] <= last[1]) {
      last[1] = Math.max(last[1], range[1]);
    } else {
      merged.push([...range]);
    }
  }

  return merged;
}

export interface CodeToken {
  content: string;
  style?: Record<string, string>;
}

export type CodeLineSegment =
  | { type: 'token'; token: CodeToken }
  | { type: 'mark'; tokens: CodeToken[] };

/** Groups the tokens of one line into plain tokens and marked runs, splitting tokens at range edges. */
export function segmentLine(tokens: readonly CodeToken[], ranges: readonly [number, number][]): CodeLineSegment[] {
  if (ranges.length === 0) {
    return tokens.map(token => ({ type: 'token', token }));
  }

  const segments: CodeLineSegment[] = [];
  let lineOffset = 0;
  let rangeIndex = 0;
  let openRange = -1;

  for (const token of tokens) {
    let position = 0;

    while (position < token.content.length) {
      const absolute = lineOffset + position;

      while (rangeIndex < ranges.length && ranges[rangeIndex][1] <= absolute) {
        rangeIndex++;
      }

      const range = ranges[rangeIndex];
      const inRange = range !== undefined && range[0] <= absolute;
      const boundary = range === undefined ? Number.POSITIVE_INFINITY : (inRange ? range[1] : range[0]) - lineOffset;
      const end = Math.min(token.content.length, boundary);
      const piece: CodeToken = { ...token, content: token.content.slice(position, end) };
      const last = segments.at(-1);

      if (!inRange) {
        segments.push({ type: 'token', token: piece });
        openRange = -1;
      } else if (last?.type === 'mark' && openRange === rangeIndex) {
        last.tokens.push(piece);
      } else {
        segments.push({ type: 'mark', tokens: [piece] });
        openRange = rangeIndex;
      }

      position = end;
    }

    lineOffset += token.content.length;
  }

  return segments;
}

import type { GrammarState, HighlighterCore, LanguageInput, ThemeInput, ThemedToken } from 'shiki/core';
import type { CodeToken } from './lines';

/**
 * Languages that can be highlighted. Each one is a separate chunk that loads the
 * first time a block uses it. Add or remove entries to change what your app ships.
 */
export const codeBlockLanguages: Record<string, LanguageInput> = {
  bash: () => import('shiki/langs/shellscript.mjs'),
  css: () => import('shiki/langs/css.mjs'),
  diff: () => import('shiki/langs/diff.mjs'),
  html: () => import('shiki/langs/html.mjs'),
  javascript: () => import('shiki/langs/javascript.mjs'),
  json: () => import('shiki/langs/json.mjs'),
  jsx: () => import('shiki/langs/jsx.mjs'),
  markdown: () => import('shiki/langs/markdown.mjs'),
  python: () => import('shiki/langs/python.mjs'),
  sql: () => import('shiki/langs/sql.mjs'),
  tsx: () => import('shiki/langs/tsx.mjs'),
  typescript: () => import('shiki/langs/typescript.mjs'),
  vue: () => import('shiki/langs/vue.mjs'),
  yaml: () => import('shiki/langs/yaml.mjs'),
};

/** Other names for the languages above. */
export const codeBlockLanguageAliases: Record<string, string> = {
  console: 'bash',
  js: 'javascript',
  jsonc: 'json',
  md: 'markdown',
  mjs: 'javascript',
  py: 'python',
  sh: 'bash',
  shell: 'bash',
  shellscript: 'bash',
  ts: 'typescript',
  yml: 'yaml',
  zsh: 'bash',
};

// The default theme. Its colors are `--code-block-*` CSS variables that follow the sigma theme and dark mode.
const CODE_BLOCK_THEME_NAME = 'sigma-code-block';

/** `'sigma'` follows the theme tokens. A pair of shiki themes switches with the `.dark` class. */
export type CodeBlockThemes = 'sigma' | { light: ThemeInput; dark: ThemeInput };

export interface CodeBlockHighlightOptions {
  themes?: CodeBlockThemes;
}

export interface LoadedCodeBlockHighlighter {
  /** The resolved language name. */
  language: string;
  /** Tokenizes code into one token array per line. Pass `state` to continue from a previous chunk. */
  highlight: (code: string, state?: GrammarState) => { lines: CodeToken[][]; state?: GrammarState };
}

let highlighterPromise: Promise<HighlighterCore> | undefined;
const themeNames = /* @__PURE__ */ new WeakMap<object, Promise<string>>();
const themeKeys = /* @__PURE__ */ new WeakMap<object, number>();
let nextThemeKey = 0;
const loaded = /* @__PURE__ */ new Map<string, Promise<LoadedCodeBlockHighlighter>>();

// shiki is imported on first use, so pages without highlighted code don't load it.
async function createHighlighter() {
  const [{ createCssVariablesTheme, createHighlighterCore }, { createJavaScriptRegexEngine }] = await Promise.all([
    import('shiki/core'),
    import('shiki/engine/javascript'),
  ]);

  return createHighlighterCore({
    themes: [createCssVariablesTheme({
      name: CODE_BLOCK_THEME_NAME,
      variablePrefix: '--code-block-',
      variableDefaults: {},
      fontStyle: true,
    })],
    langs: [],
    engine: createJavaScriptRegexEngine({ forgiving: true }),
  });
}

function getHighlighter() {
  highlighterPromise ??= createHighlighter().catch((error: unknown) => {
    highlighterPromise = undefined;
    throw error;
  });

  return highlighterPromise;
}

/** Returns the language name to load, `'ansi'`, or `null` for a language that isn't listed. */
export function resolveCodeBlockLanguage(language: string | undefined | null): string | null {
  if (!language) {
    return null;
  }

  const name = language.trim().toLowerCase();

  if (name === 'ansi') {
    return name;
  }

  if (name in codeBlockLanguages) {
    return name;
  }

  return codeBlockLanguageAliases[name] ?? null;
}

async function loadTheme(highlighter: HighlighterCore, theme: ThemeInput): Promise<string> {
  const key = theme as object;
  let name = themeNames.get(key);

  if (!name) {
    name = (async () => {
      const loaded = await (typeof theme === 'function' ? (theme as () => Promise<unknown>)() : theme);
      const resolved = ((loaded as { default?: unknown }).default ?? loaded) as { name?: string };
      await highlighter.loadTheme(resolved as ThemeInput);
      return resolved.name ?? 'custom';
    })();
    themeNames.set(key, name);
  }

  return name;
}

function fontStyleOf(token: ThemedToken): Record<string, string> {
  const style: Record<string, string> = {};
  const fontStyle = token.fontStyle ?? 0;

  if (fontStyle & 1) {
    style['font-style'] = 'italic';
  }

  if (fontStyle & 2) {
    style['font-weight'] = '600';
  }

  if (fontStyle & 4) {
    style['text-decoration'] = 'underline';
  }

  return style;
}

function getThemesKey(themes: CodeBlockThemes) {
  if (themes === 'sigma') {
    return 'sigma';
  }

  if (!themeKeys.has(themes)) {
    themeKeys.set(themes, ++nextThemeKey);
  }

  return `${themeKeys.get(themes)}`;
}

/**
 * Loads the highlighter and the language. Resolves to `null` for a language that isn't listed.
 * The same language and themes resolve to the same instance.
 */
export function loadCodeBlockHighlighter(
  language: string | undefined | null,
  options: CodeBlockHighlightOptions = {},
): Promise<LoadedCodeBlockHighlighter | null> {
  const lang = resolveCodeBlockLanguage(language);

  if (!lang) {
    return Promise.resolve(null);
  }

  const themes = options.themes ?? 'sigma';
  const key = `${lang}:${getThemesKey(themes)}`;
  let entry = loaded.get(key);

  if (!entry) {
    entry = createLoadedHighlighter(lang, themes).catch((error: unknown) => {
      loaded.delete(key);
      throw error;
    });
    loaded.set(key, entry);
  }

  return entry;
}

async function createLoadedHighlighter(lang: string, themes: CodeBlockThemes): Promise<LoadedCodeBlockHighlighter> {
  const highlighter = await getHighlighter();

  if (lang !== 'ansi' && !highlighter.getLoadedLanguages().includes(lang)) {
    await highlighter.loadLanguage(codeBlockLanguages[lang]);
  }

  const dual = themes === 'sigma'
    ? null
    : { light: await loadTheme(highlighter, themes.light), dark: await loadTheme(highlighter, themes.dark) };

  const tokenize = (code: string, state?: GrammarState) => {
    if (dual) {
      const result = highlighter.codeToTokens(code, {
        lang,
        themes: dual,
        defaultColor: false,
        grammarState: state,
      });

      return {
        state: result.grammarState,
        lines: result.tokens.map(line => line.map(token => ({
          content: token.content,
          style: { ...(token.htmlStyle as Record<string, string> | undefined) },
        }))),
      };
    }

    const result = highlighter.codeToTokens(code, { lang, theme: CODE_BLOCK_THEME_NAME, grammarState: state });

    return {
      state: result.grammarState,
      lines: result.tokens.map(line => line.map(token => ({
        content: token.content,
        style: { color: token.color ?? 'var(--code-block-foreground)', ...fontStyleOf(token) },
      }))),
    };
  };

  return {
    language: lang,
    highlight(code, state) {
      // ANSI has no grammar state, so each line is tokenized on its own.
      if (lang === 'ansi') {
        return { lines: code.split('\n').map(line => tokenize(line).lines[0] ?? []) };
      }

      return tokenize(code, state);
    },
  };
}

/**
 * Highlights code in one call, for server rendering or build time.
 * The result is plain JSON, so it can be serialized into the page payload.
 */
export async function highlightCode(
  code: string,
  language: string,
  options: CodeBlockHighlightOptions = {},
): Promise<CodeToken[][] | null> {
  const highlighter = await loadCodeBlockHighlighter(language, options);
  return highlighter ? highlighter.highlight(code).lines : null;
}

import {
  type MaybeRefOrGetter,
  type Ref,
  type ShallowRef,
  getCurrentInstance,
  onBeforeUnmount,
  onMounted,
  ref,
  shallowRef,
  toValue,
  watch,
} from 'vue';
import type { GrammarState } from 'shiki/core';
import { type CodeBlockHighlightOptions, type LoadedCodeBlockHighlighter, loadCodeBlockHighlighter } from './highlighter';
import { type CodeToken, type PrepareCodeOptions, prepareCode } from './lines';

export interface UseHighlightedCodeOptions extends CodeBlockHighlightOptions, PrepareCodeOptions {
  /** Tokens rendered on the server, so hydration matches before the client highlighter loads. */
  initial?: CodeToken[][] | null;
}

export interface UseHighlightedCodeReturn {
  /** One token array per rendered line, or `null` until highlighting finishes or for an unknown language. */
  lines: ShallowRef<CodeToken[][] | null>;
  /** True while the highlighter or the language is loading. */
  loading: Ref<boolean>;
  /** The last loading error, if any. */
  error: ShallowRef<unknown>;
}

interface Progress {
  highlighter: LoadedCodeBlockHighlighter;
  text: string;
  lines: CodeToken[][];
  state?: GrammarState;
}

/**
 * Highlights code with shiki in the browser. Pass `diff` and `notation` with the same
 * values as on `CodeBlockContent`, so the token lines match the rendered lines.
 *
 * While the code grows, as it does when it streams, only the new lines are tokenized.
 */
export function useHighlightedCode(
  code: MaybeRefOrGetter<string | undefined>,
  language: MaybeRefOrGetter<string | undefined>,
  options: MaybeRefOrGetter<UseHighlightedCodeOptions> = {},
): UseHighlightedCodeReturn {
  const lines = shallowRef<CodeToken[][] | null>(toValue(options).initial ?? null);
  const loading = ref(false);
  const error = shallowRef<unknown>();
  let progress: Progress | null = null;
  let request = 0;
  let stopped = false;

  function tokenize(highlighter: LoadedCodeBlockHighlighter, source: string) {
    if (progress?.highlighter !== highlighter || !source.startsWith(progress.text)) {
      progress = { highlighter, text: '', lines: [] };
    }

    // Complete lines are kept; only lines after the last newline are tokenized again.
    const end = source.lastIndexOf('\n') + 1;

    if (end > progress.text.length) {
      const chunk = highlighter.highlight(source.slice(progress.text.length, end - 1), progress.state);
      progress = {
        highlighter,
        text: source.slice(0, end),
        lines: [...progress.lines, ...chunk.lines],
        state: chunk.state,
      };
    }

    const tail = highlighter.highlight(source.slice(end), progress.state).lines[0] ?? [];
    return [...progress.lines, tail];
  }

  async function update() {
    const current = ++request;
    const resolvedOptions = toValue(options);
    const source = prepareCode(toValue(code) ?? '', resolvedOptions).code;

    loading.value = true;

    try {
      const highlighter = await loadCodeBlockHighlighter(toValue(language), resolvedOptions);

      if (stopped || current !== request) {
        return;
      }

      lines.value = highlighter ? tokenize(highlighter, source) : null;
      error.value = undefined;
    } catch (cause) {
      if (current === request) {
        error.value = cause;
        lines.value = null;
      }
    } finally {
      if (current === request) {
        loading.value = false;
      }
    }
  }

  function start() {
    watch(
      () => [toValue(code), toValue(language), toValue(options)] as const,
      () => update(),
      { immediate: true, deep: true },
    );
  }

  // Nothing runs during server rendering, so the server and the first client render match.
  if (getCurrentInstance()) {
    onMounted(start);
    onBeforeUnmount(() => {
      stopped = true;
    });
  } else if (typeof window !== 'undefined') {
    start();
  }

  return { lines, loading, error };
}
